<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue';
import { api, credits, dateTime } from './api';
import Icon from './Icon.vue';

const state = ref({ app: { name: 'Promex' }, user: null, navigation: [] });
const initial = new URL(window.__PROMEX_SPA_PATH__ || location.pathname, location.origin);
const path = ref(normalize(initial.pathname));
const loading = ref(true), loadingGames = ref(false), loadingSports = ref(false), searching = ref(false);
const savingProfile = ref(false), savingPassword = ref(false), error = ref(''), notice = ref('');
const games = ref([]), recentGames = ref(readRecent()), gamesTotal = ref(0), gamePage = ref(1);
const gameCategory = ref(initial.searchParams.get('category') || 'hot'), searchQuery = ref(initial.searchParams.get('q') || '');
const sports = ref([]), sport = ref('all'), slip = ref([]), stake = ref('100'), mobileSlipOpen = ref(false), launching = ref(null);
const profile = ref(null), vip = ref(null), affiliates = ref(null);
const profileMenuOpen = ref(false), accountMenu = ref(null);
const accountSection = ref(initial.searchParams.get('section') || 'confirmation');
const profileForm = reactive({ first_name: '', last_name: '', email: '', phone: '' });
const passwordForm = reactive({ old_password: '', password: '', password_confirmation: '' });
const categories = [['hot', 'Em alta'], ['all', 'Todos'], ['new', 'Novos'], ['cedar_games', 'Originais'], ['cedar_remakes', 'Slots']];
const mobileNav = [['/app', 'home', 'Início'], ['/app/jogos', 'games', 'Jogos'], ['/app/esportes', 'sports', 'Esportes'], ['/app/vip', 'vip', 'VIP'], ['/app/perfil', 'user', 'Conta']];
const page = computed(() => ({ '/app': 'home', '/app/jogos': 'games', '/app/esportes': 'sports', '/app/perfil': 'profile', '/app/vip': 'vip', '/app/afiliados': 'affiliates', '/app/ajuda': 'info', '/app/beneficios': 'benefits', '/app/progresso': 'progress' }[path.value] || 'home'));
const currentInfo = computed(() => ({
    info: ['Central de ajuda', 'Encontre respostas rápidas sobre sua conta, jogos, créditos sociais e segurança.', ['Como funcionam os créditos sociais?', 'Use os créditos Promex para explorar a plataforma. Eles não representam dinheiro ou pagamento externo.'], ['Precisa de suporte?', 'Acesse sua conta para consultar os canais de suporte disponíveis.']],
    benefits: ['Benefícios Promex', 'Uma experiência social com catálogo progressivo, desafios e recompensas de fidelidade.', ['Catálogo sempre acessível', 'Descubra jogos por categoria ou encontre rapidamente pelo nome.'], ['Clube VIP', 'Acompanhe sua evolução e os benefícios sociais diretamente pelo seu perfil.']],
    progress: ['Seu progresso', 'Acompanhe atividades, nível VIP e metas de experiência no mesmo lugar.', ['Evolução transparente', 'O nível e o progresso exibidos na conta são atualizados conforme as atividades elegíveis.'], ['Próximo passo', 'Entre para conferir sua trajetória e os benefícios disponíveis.']],
}[page.value] || []));
const pageMeta = computed(() => ({
    home: ['Promex | Jogos sociais', 'Jogos, esportes e recompensas em créditos sociais.'],
    games: ['Jogos sociais | Promex', 'Explore o catálogo de jogos sociais Promex.'],
    sports: ['Esportes sociais | Promex', 'Acompanhe partidas e palpites com créditos sociais.'],
    profile: ['Minha conta | Promex', 'Acompanhe sua conta, saldo social e histórico.'],
    vip: ['Clube VIP | Promex', 'Acompanhe seu nível, XP e benefícios sociais.'],
    affiliates: ['Indique e ganhe | Promex', 'Convide amigos e acompanhe créditos sociais.'],
    info: ['Central de ajuda | Promex', 'Respostas sobre conta, jogos e créditos sociais.'],
    benefits: ['Benefícios | Promex', 'Conheça os benefícios sociais da plataforma Promex.'],
    progress: ['Progresso | Promex', 'Acompanhe sua evolução social no Promex.'],
}[page.value] || []));

function normalize(value) { return value.startsWith('/app') ? (value.replace(/\/$/, '') || '/app') : '/app'; }
function readRecent() { try { return JSON.parse(localStorage.getItem('promex:recent-games') || '[]').slice(0, 10); } catch { return []; } }
function rememberGame(game) { recentGames.value = [game, ...recentGames.value.filter((item) => item.url !== game.url)].slice(0, 10); localStorage.setItem('promex:recent-games', JSON.stringify(recentGames.value)); }
function setMessage(type, value) { if (type === 'error') error.value = value; else notice.value = value; window.setTimeout(() => { if (type === 'error' && error.value === value) error.value = ''; if (type === 'notice' && notice.value === value) notice.value = ''; }, 4500); }
function categoryUrl(category) { return `/app/jogos?category=${encodeURIComponent(category)}`; }
function go(to) { profileMenuOpen.value = false; if (!to.startsWith('/app')) { location.assign(to); return; } const target = new URL(to, location.origin); history.pushState({}, '', target.pathname + target.search); path.value = normalize(target.pathname); gameCategory.value = target.searchParams.get('category') || (path.value === '/app/jogos' ? 'all' : 'hot'); searchQuery.value = target.searchParams.get('q') || ''; if (path.value === '/app/perfil') accountSection.value = target.searchParams.get('section') || 'confirmation'; window.scrollTo({ top: 0, behavior: 'instant' }); }
function openAccount(section = 'confirmation') { go(`/app/perfil?section=${section}`); }
function setCategory(category) {
    if (page.value !== 'games') { go(categoryUrl(category)); return; }
    if (gameCategory.value === category && !searchQuery.value) return;
    const searchWillChange = searchQuery.value !== '';
    if (searchWillChange) ignoreNextSearchReload = true;
    gameCategory.value = category;
    searchQuery.value = '';
    history.pushState({}, '', categoryUrl(category));
    clearTimeout(searchTimer);
    loadGames({ reset: true, query: '' });
}
async function bootstrap() { state.value = await api('/spa/api/bootstrap'); }
async function loadGames({ reset = false, query = searchQuery.value } = {}) {
    const requestId = ++gamesRequestId;
    if (reset) { games.value = []; gamePage.value = 1; }
    loadingGames.value = true;
    try { const category = query.trim() ? 'all' : gameCategory.value; const args = new URLSearchParams({ category, page: String(gamePage.value), per_page: '15' }); if (query.trim()) args.set('q', query.trim()); const data = await api(`/catalog.json?${args}`); if (requestId !== gamesRequestId) return; games.value = reset ? data.items : [...games.value, ...data.items]; gamesTotal.value = data.total || games.value.length; gamePage.value = data.next_page || 0; } catch (e) { if (requestId === gamesRequestId) setMessage('error', e.message); } finally { if (requestId === gamesRequestId) loadingGames.value = false; }
}
async function loadSports() { loadingSports.value = true; try { sports.value = (await api(`/spa/api/sports?sport=${sport.value}`)).matches; } catch (e) { setMessage('error', e.message); } finally { loadingSports.value = false; } }
async function loadProfile() { if (!state.value.user) { profile.value = null; return; } try { profile.value = await api('/spa/api/profile'); Object.assign(profileForm, profile.value.user); } catch { profile.value = null; } }
async function loadVip() { try { vip.value = await api('/spa/api/vip'); } catch (e) { setMessage('error', e.message); } }
async function loadAffiliates() { if (!state.value.user) { affiliates.value = null; return; } try { affiliates.value = await api('/spa/api/affiliates'); } catch { affiliates.value = null; } }
async function loadCurrent() { if (page.value === 'home' || page.value === 'games') await loadGames({ reset: true }); if (page.value === 'sports') await loadSports(); if (page.value === 'profile') await loadProfile(); if (page.value === 'vip') await loadVip(); if (page.value === 'affiliates') await loadAffiliates(); }
function launchGame(game) { rememberGame(game); launching.value = game; window.setTimeout(() => { location.assign(game.url); }, 220); }
function selectOdd(match, selection) { const key = `${match.id}:${selection}`; const exists = slip.value.findIndex((item) => item.key === key); slip.value = exists >= 0 ? slip.value.filter((_, index) => index !== exists) : [...slip.value.filter((item) => item.match_id !== match.id), { key, match_id: match.id, home: match.home, away: match.away, selection, odds: match.odds[selection] }]; if (slip.value.length) mobileSlipOpen.value = true; }
function selected(match, selection) { return slip.value.some((item) => item.key === `${match.id}:${selection}`); }
function removeSlip(key) { slip.value = slip.value.filter((item) => item.key !== key); }
async function placeBet() { if (!state.value.user) { go('/register'); return; } if (!slip.value.length) { setMessage('error', 'Selecione ao menos um palpite.'); return; } try { const result = await api('/sports/bet', { method: 'POST', body: JSON.stringify({ type: slip.value.length > 1 ? 'parlay' : 'single', stake: Number(stake.value), legs: slip.value }) }); setMessage('notice', result.message || 'Palpite registrado.'); slip.value = []; mobileSlipOpen.value = false; await bootstrap(); } catch (e) { setMessage('error', e.message); } }
async function claim(endpoint) { try { const result = await api(endpoint, { method: 'POST', body: '{}' }); setMessage('notice', result.message || 'Créditos adicionados.'); await bootstrap(); await loadCurrent(); } catch (e) { setMessage('error', e.message); } }
async function saveProfile() { savingProfile.value = true; try { const result = await api('/spa/api/profile', { method: 'PATCH', body: JSON.stringify(profileForm) }); profile.value.user = result.user; state.value.user = result.user; setMessage('notice', result.message); } catch (e) { setMessage('error', e.message); } finally { savingProfile.value = false; } }
async function savePassword() { savingPassword.value = true; try { const result = await api('/spa/api/profile/password', { method: 'POST', body: JSON.stringify(passwordForm) }); Object.assign(passwordForm, { old_password: '', password: '', password_confirmation: '' }); setMessage('notice', result.message); } catch (e) { setMessage('error', e.message); } finally { savingPassword.value = false; } }
async function copy(value) { try { await navigator.clipboard.writeText(value); setMessage('notice', 'Link copiado.'); } catch { setMessage('error', 'Não foi possível copiar o link.'); } }
function updateMeta() { const [title, description] = pageMeta.value; document.title = title; document.querySelector('meta[name="description"]')?.setAttribute('content', description); }
function hideDecorativeIcons() { document.querySelectorAll('.spa-home-categories b').forEach((icon) => icon.setAttribute('aria-hidden', 'true')); }
function closeProfileMenuOnOutsideClick(event) { if (!accountMenu.value?.contains(event.target)) profileMenuOpen.value = false; }
let searchTimer;
let ignoreNextSearchReload = false;
let gamesRequestId = 0;
watch(searchQuery, (value) => { if (page.value !== 'games') return; if (ignoreNextSearchReload) { ignoreNextSearchReload = false; return; } const params = new URLSearchParams({ category: gameCategory.value }); if (value.trim()) params.set('q', value.trim()); history.replaceState({}, '', `/app/jogos?${params}`); clearTimeout(searchTimer); searching.value = true; searchTimer = window.setTimeout(async () => { await loadGames({ reset: true, query: value }); searching.value = false; }, 280); });
watch(page, async () => { updateMeta(); error.value = ''; notice.value = ''; await loadCurrent(); }); watch(sport, loadSports);
onMounted(async () => { updateMeta(); hideDecorativeIcons(); document.addEventListener('click', closeProfileMenuOnOutsideClick); window.addEventListener('popstate', () => { const url = new URL(location.href); path.value = normalize(url.pathname); gameCategory.value = url.searchParams.get('category') || 'all'; searchQuery.value = url.searchParams.get('q') || ''; if (path.value === '/app/perfil') accountSection.value = url.searchParams.get('section') || 'confirmation'; }); try { await bootstrap(); await loadCurrent(); } catch (e) { setMessage('error', e.message); } finally { loading.value = false; } });
onBeforeUnmount(() => document.removeEventListener('click', closeProfileMenuOnOutsideClick));
</script>

<template>
  <div class="spa-shell" :class="`page-${page}`">
    <header class="spa-nav"><div class="spa-container spa-nav__inner"><a class="spa-brand" href="/app" @click.prevent="go('/app')">PROMEX</a><nav class="spa-nav__links" aria-label="Navegação principal"><a v-for="item in state.navigation" :key="item.to" :href="item.to" :class="{ active: path === item.to }" @click.prevent="go(item.to)">{{ item.label }}</a></nav><div class="spa-nav__actions"><template v-if="state.user"><span class="spa-balance"><small>Saldo social</small>{{ credits(state.user.balance) }} {{ state.user.currency }}</span><div ref="accountMenu" class="spa-account-menu" @keydown.esc="profileMenuOpen = false"><button class="spa-profile-trigger" type="button" aria-label="Abrir menu do perfil" aria-controls="menu-perfil" :aria-expanded="profileMenuOpen" @click.stop="profileMenuOpen = !profileMenuOpen"><Icon name="user" :size="20" /></button><transition name="spa-menu"><section v-if="profileMenuOpen" id="menu-perfil" class="spa-profile-popover" aria-label="Informações da conta" role="menu"><header class="spa-profile-popover__header"><div><span>Informações da conta</span><strong>{{ state.user.username }}</strong></div><button type="button" @click="openAccount('confirmation')">Conta</button></header><div class="spa-profile-balance"><div><span>Saldo social</span><strong>{{ credits(state.user.balance) }} {{ state.user.currency }}</strong></div><div><span>Nível VIP</span><strong>{{ state.user.vip_level || 1 }}</strong></div><button class="spa-primary spa-full" type="button" @click="openAccount('balance')">Depositar <Icon name="arrow-right" :size="15" /></button></div><div class="spa-profile-shortcuts"><a href="/app/ajuda" role="menuitem" @click.prevent="go('/app/ajuda')"><i><Icon name="help" :size="20" /></i><span>Suporte</span></a><a href="/app/ajuda" role="menuitem" @click.prevent="go('/app/ajuda')"><i><Icon name="message" :size="20" /></i><span>Perguntas frequentes</span></a></div><a class="spa-profile-logout" href="/logout" role="menuitem"><Icon name="logout" :size="16" /> Sair da conta</a></section></transition></div></template><template v-else><a class="spa-login" href="/login">Entrar</a><a class="spa-signup" href="/register">Criar conta</a></template></div></div></header>
    <main class="spa-container spa-main" id="conteudo"><div class="spa-live" aria-live="polite" aria-atomic="true"><div v-if="error" class="spa-notice spa-error">{{ error }}</div><div v-if="notice" class="spa-notice">{{ notice }}</div></div><div v-if="loading" class="spa-skeletons" aria-label="Carregando conteúdo"><i v-for="n in 5" :key="n"></i></div>
      <template v-else-if="page === 'home'"><section class="spa-card spa-hero"><div class="spa-hero__content"><div class="eyebrow">Jogos sociais Promex</div><h1>Descubra sua próxima experiência.</h1><p class="spa-muted">Jogos, esportes e evolução com créditos sociais em um só lugar.</p><div class="spa-actions"><a v-if="!state.user" class="spa-primary" href="/register">Criar conta</a><a v-else class="spa-primary" href="/app/jogos" @click.prevent="go('/app/jogos')">Explorar jogos</a><a class="spa-secondary" href="/app/esportes" @click.prevent="go('/app/esportes')">Ver esportes</a></div></div></section><section class="spa-home-stats" aria-label="Destaques"><article><strong>{{ gamesTotal || '+' }}</strong><span>jogos no catálogo</span></article><article><strong>AO VIVO</strong><span>partidas e palpites</span></article><article><strong>VIP</strong><span>evolução social</span></article><article><strong>100%</strong><span>créditos Promex</span></article></section><nav class="spa-home-categories" aria-label="Atalhos"><a href="/app/esportes" @click.prevent="go('/app/esportes')"><b>◉</b> Esportes</a><a :href="categoryUrl('cedar_remakes')" @click.prevent="setCategory('cedar_remakes')"><b>♜</b> Slots</a><a :href="categoryUrl('cedar_games')" @click.prevent="setCategory('cedar_games')"><b>✦</b> Originais</a><a :href="categoryUrl('all')" @click.prevent="setCategory('all')"><b>♠</b> Catálogo</a><a href="/app/vip" @click.prevent="go('/app/vip')"><b>✦</b> VIP</a><a href="/app/afiliados" @click.prevent="go('/app/afiliados')"><b>♧</b> Indique</a></nav><section v-if="recentGames.length" class="spa-section"><div class="spa-section__header"><div><div class="eyebrow">Seu histórico local</div><h2>Vistos recentemente</h2></div></div><div class="spa-games"><button v-for="game in recentGames.slice(0,5)" :key="game.url" class="spa-game" @click="launchGame(game)"><img :src="game.cover_url" :alt="game.title" width="300" height="400" loading="lazy"><span><small>{{ game.provider }}</small>{{ game.title }}</span></button></div></section><section class="spa-section"><div class="spa-section__header"><div><div class="eyebrow">Seleção Promex</div><h2>Jogos em destaque</h2></div><a class="spa-secondary" href="/app/jogos" @click.prevent="go('/app/jogos')">Ver catálogo</a></div><div v-if="loadingGames" class="spa-game-skeletons"><i v-for="n in 5" :key="n"></i></div><div v-else class="spa-games"><button v-for="game in games.slice(0,10)" :key="game.url" class="spa-game" @click="launchGame(game)"><img :src="game.cover_url" :alt="game.title" width="300" height="400" loading="lazy"><span><small>{{ game.provider }}</small>{{ game.title }}</span></button></div></section></template>
      <template v-else-if="page === 'games'"><section class="spa-section"><div class="spa-section__header spa-section__header--stack"><div><div class="eyebrow">Catálogo progressivo</div><h1>Arena de jogos</h1><p class="spa-muted">{{ gamesTotal }} jogos disponíveis. Use busca ou uma categoria para descobrir algo novo.</p></div><label class="spa-search"><span>⌕</span><input v-model="searchQuery" type="search" placeholder="Buscar por nome do jogo" aria-label="Buscar jogos"><em v-if="searching">Buscando…</em></label></div><div class="spa-pills" aria-label="Categorias"><button v-for="[key,label] in categories" :key="key" class="spa-pill" :class="{active: gameCategory === key && !searchQuery}" @click="setCategory(key)">{{ label }}</button></div><div v-if="loadingGames && !games.length" class="spa-game-skeletons"><i v-for="n in 10" :key="n"></i></div><div v-else class="spa-games spa-games--catalog"><button v-for="game in games" :key="game.url" class="spa-game" @click="launchGame(game)"><img :src="game.cover_url" :alt="game.title" width="300" height="400" loading="lazy"><span><small>{{ game.provider }}</small>{{ game.title }}<b>Abrir jogo →</b></span></button></div><div v-if="!games.length && !loadingGames" class="spa-empty spa-card"><h2>Nenhum jogo encontrado</h2><p>Tente outro termo ou explore todo o catálogo.</p><button class="spa-primary" @click="searchQuery = ''; setCategory('all')">Explorar jogos</button></div><div v-if="gamePage" class="spa-load-more"><button class="spa-secondary" :disabled="loadingGames" @click="loadGames()">{{ loadingGames ? 'Carregando…' : 'Ver mais jogos' }}</button></div></section></template>
      <template v-else-if="page === 'sports'"><section class="spa-section"><div class="eyebrow">Palpites sociais</div><h1>Arena de esportes</h1><p class="spa-muted">Use seus créditos sociais para montar palpites de demonstração.</p><div class="spa-pills spa-sport-filters"><button v-for="item in [['all','Todos'],['soccer','Futebol'],['basketball','Basquete'],['mma','MMA']]" :key="item[0]" class="spa-pill" :class="{active:sport===item[0]}" @click="sport=item[0]">{{ item[1] }}</button></div><div class="spa-sports"><div><div v-if="loadingSports" class="spa-skeletons spa-skeletons--list"><i v-for="n in 3" :key="n"></i></div><article v-for="match in sports" :key="match.id" class="spa-card spa-match"><div class="spa-match__top"><span>{{ match.sport }}</span><time>{{ dateTime(match.starts_at) }}</time></div><div class="spa-teams">{{ match.home }} <span class="spa-muted">×</span> {{ match.away }}</div><div class="spa-odds"><button v-for="[key,label] in [['home','1'],['draw','X'],['away','2']]" :key="key" class="spa-odd" :class="{selected:selected(match,key)}" @click="selectOdd(match,key)">{{ label }} <b>{{ match.odds[key].toFixed(2) }}</b></button></div></article><div v-if="!loadingSports && !sports.length" class="spa-empty spa-card"><h2>Sem partidas abertas agora</h2><p>Atualize a agenda ou volte ao catálogo enquanto novos eventos são preparados.</p><button class="spa-primary" @click="loadSports">Atualizar agenda</button><button class="spa-secondary" @click="go('/app/jogos')">Explorar jogos</button></div></div><aside class="spa-card spa-slip" :class="{ 'spa-slip--open': mobileSlipOpen }"><button class="spa-slip__toggle" @click="mobileSlipOpen = !mobileSlipOpen"><span>Bilhete</span><b>{{ slip.length }} seleção{{ slip.length === 1 ? '' : 'ões' }}</b></button><div class="spa-slip__body"><div class="eyebrow">Bilhete social</div><h2>Seus palpites</h2><div v-if="!slip.length" class="spa-empty">Selecione uma cotação para montar o bilhete.</div><div v-for="item in slip" :key="item.key" class="spa-slip__item"><button aria-label="Remover seleção" @click="removeSlip(item.key)">×</button>{{ item.home }} × {{ item.away }}<br><span class="spa-muted">{{ item.selection }} · {{ item.odds.toFixed(2) }}</span></div><label>Créditos por palpite<input v-model="stake" class="spa-input" type="number" min="1"></label><button class="spa-primary spa-full" :disabled="!slip.length" @click="placeBet">{{ state.user ? 'Confirmar palpite' : 'Entre para palpitar' }}</button></div></aside></div></section></template>
      <template v-else-if="page === 'profile'"><section class="spa-section spa-account-page"><div v-if="!profile" class="spa-empty spa-card"><h2>Entre para acessar sua conta</h2><p>Seu saldo social, nível VIP e histórico ficam disponíveis após o login.</p><a class="spa-primary" href="/login">Entrar</a><a class="spa-secondary" href="/register">Criar conta</a></div><template v-else><div class="spa-account-shell"><aside class="spa-account-sidebar"><div class="spa-account-user"><i><Icon name="user" :size="46" /></i><strong>{{ profile.user.username }}</strong><span>Conta Promex</span></div><div class="spa-account-sidebar__balance"><span>Saldo social</span><strong>{{ credits(profile.user.balance) }} {{ profile.user.currency }}</strong><button class="spa-primary" type="button" @click="accountSection = 'balance'">Depositar</button></div><nav aria-label="Seções da conta"><button type="button" :class="{active:accountSection === 'confirmation'}" @click="accountSection = 'confirmation'"><Icon name="help" :size="19" /> Confirmação</button><button type="button" :class="{active:accountSection === 'profile'}" @click="accountSection = 'profile'"><Icon name="user" :size="19" /> Dados pessoais</button><button type="button" :class="{active:accountSection === 'balance'}" @click="accountSection = 'balance'"><Icon name="wallet" :size="19" /> Saldo</button><button type="button" :class="{active:accountSection === 'offers'}" @click="accountSection = 'offers'"><Icon name="gift" :size="19" /> Códigos e benefícios</button><button type="button" :class="{active:accountSection === 'password'}" @click="accountSection = 'password'"><Icon name="lock" :size="19" /> Senha</button><button type="button" :class="{active:accountSection === 'settings'}" @click="accountSection = 'settings'"><Icon name="settings" :size="19" /> Preferências</button><a href="/logout"><Icon name="logout" :size="19" /> Sair</a></nav></aside><div class="spa-account-content"><template v-if="accountSection === 'confirmation'"><div class="spa-account-title"><div><div class="eyebrow">Conta</div><h1>Confirmação</h1><p class="spa-muted">Confira os dados de contato da sua conta.</p></div></div><section class="spa-account-contact"><article><div class="spa-account-contact__icon"><Icon name="message" :size="27" /></div><div class="spa-account-contact__body"><h2>E-mail</h2><label>E-mail<input :value="profile.user.email" readonly></label><button class="spa-secondary" type="button" @click="accountSection = 'profile'">Editar dados</button></div><div class="spa-account-contact__status"><span>Status</span><strong :class="{ 'is-ok': profile.user.email_verified_at }">{{ profile.user.email_verified_at ? 'Confirmado' : 'Em revisão' }}</strong><p>Use um e-mail válido para receber informações importantes da sua conta.</p></div></article><article><div class="spa-account-contact__icon"><Icon name="user" :size="27" /></div><div class="spa-account-contact__body"><h2>Celular</h2><label>Telefone<input :value="profile.user.phone || 'Não informado'" readonly></label><button class="spa-secondary" type="button" @click="accountSection = 'profile'">Editar dados</button></div><div class="spa-account-contact__status"><span>Status</span><strong :class="{ 'is-ok': profile.user.phone }">{{ profile.user.phone ? 'Cadastrado' : 'Não informado' }}</strong><p>Mantenha o telefone atualizado para proteger o acesso à conta.</p></div></article></section></template><template v-else-if="accountSection === 'profile'"><div class="spa-account-title"><div><div class="eyebrow">Conta</div><h1>Dados pessoais</h1><p class="spa-muted">Mantenha suas informações atualizadas.</p></div></div><form class="spa-card spa-form" @submit.prevent="saveProfile"><div class="spa-form__grid"><label>Nome<input v-model="profileForm.first_name" autocomplete="given-name"></label><label>Sobrenome<input v-model="profileForm.last_name" autocomplete="family-name"></label><label>E-mail<input v-model="profileForm.email" type="email" autocomplete="email"></label><label>Telefone<input v-model="profileForm.phone" type="tel" autocomplete="tel"></label></div><button class="spa-primary" :disabled="savingProfile">{{ savingProfile ? 'Salvando…' : 'Salvar alterações' }}</button></form></template><template v-else-if="accountSection === 'balance'"><div class="spa-account-title"><div><div class="eyebrow">Conta</div><h1>Saldo</h1><p class="spa-muted">Acompanhe seus créditos sociais Promex.</p></div></div><section class="spa-account-balance-card"><div><span>Créditos sociais disponíveis</span><strong>{{ credits(profile.user.balance) }} {{ profile.user.currency }}</strong><p>Os créditos sociais são internos e não representam dinheiro, saque ou pagamento externo.</p></div><button class="spa-primary" type="button" @click="go('/app/jogos')">Explorar jogos <Icon name="arrow-right" :size="16" /></button></section><section class="spa-card spa-table-card"><h2>Palpites recentes</h2><div v-if="!profile.recent_bets.length" class="spa-empty">Você ainda não registrou palpites. <button class="spa-text-link" @click="go('/app/esportes')">Explorar esportes</button></div><table v-else class="spa-table"><thead><tr><th>Tipo</th><th>Créditos</th><th>Retorno</th><th>Status</th></tr></thead><tbody><tr v-for="bet in profile.recent_bets" :key="bet.id"><td>{{ bet.type }}</td><td>{{ credits(bet.stake) }}</td><td>{{ credits(bet.potential_win) }}</td><td>{{ bet.status }}</td></tr></tbody></table></section></template><template v-else-if="accountSection === 'offers'"><div class="spa-account-title"><div><div class="eyebrow">Conta</div><h1>Códigos e benefícios</h1><p class="spa-muted">Acompanhe os benefícios sociais e indique amigos.</p></div></div><section class="spa-card spa-account-empty"><Icon name="gift" :size="34" /><h2>Benefícios Promex</h2><p class="spa-muted">Seu nível VIP e seus créditos de indicação ficam disponíveis nesta área.</p><button class="spa-primary" type="button" @click="go('/app/vip')">Ver clube VIP</button><button class="spa-secondary" type="button" @click="go('/app/afiliados')">Indicar amigos</button></section></template><template v-else-if="accountSection === 'password'"><div class="spa-account-title"><div><div class="eyebrow">Conta</div><h1>Senha</h1><p class="spa-muted">Use uma senha forte, com pelo menos 8 caracteres.</p></div></div><form class="spa-card spa-form spa-form--narrow" @submit.prevent="savePassword"><label>Senha atual<input v-model="passwordForm.old_password" type="password" autocomplete="current-password" required></label><label>Nova senha<input v-model="passwordForm.password" type="password" autocomplete="new-password" minlength="8" required></label><label>Confirmar nova senha<input v-model="passwordForm.password_confirmation" type="password" autocomplete="new-password" minlength="8" required></label><button class="spa-secondary" :disabled="savingPassword">{{ savingPassword ? 'Atualizando…' : 'Alterar senha' }}</button></form></template><template v-else><div class="spa-account-title"><div><div class="eyebrow">Conta</div><h1>Preferências</h1><p class="spa-muted">Defina como prefere receber comunicações do Promex.</p></div></div><section class="spa-card spa-account-empty"><Icon name="settings" :size="34" /><h2>Comunicações</h2><p class="spa-muted">As preferências avançadas de notificações estarão disponíveis em breve.</p></section></template></div></div></template></section></template>
      <template v-else-if="page === 'vip'"><section class="spa-section"><div class="eyebrow">Fidelidade</div><h1>Clube VIP</h1><p class="spa-muted">Acompanhe sua evolução e benefícios sociais.</p><div v-if="!vip" class="spa-skeletons"><i v-for="n in 4" :key="n"></i></div><template v-else><div class="spa-grid spa-grid--four"><div class="spa-card spa-metric"><span>Nível atual</span><strong>{{ vip.profile.vip_level }}</strong></div><div class="spa-card spa-metric"><span>XP</span><strong>{{ credits(vip.profile.vip_xp) }}</strong></div><div class="spa-card spa-metric"><span>Progresso</span><strong>{{ Number(vip.profile.progress_pct || 0).toFixed(0) }}%</strong></div><div class="spa-card spa-metric"><span>Resgate disponível</span><strong>{{ credits(vip.profile.unclaimed_rakeback) }}</strong><button v-if="state.user" class="spa-primary" @click="claim('/spa/api/vip/claim')">Resgatar</button></div></div><div class="spa-grid spa-vip-tiers"><article v-for="tier in vip.tiers" :key="tier.name" class="spa-card spa-metric"><span>{{ tier.name }}</span><strong>{{ credits(tier.threshold) }} XP</strong><p class="spa-muted">{{ tier.rakeback }}% de retorno social</p></article></div></template></section></template>
      <template v-else-if="page === 'affiliates'"><section class="spa-section"><div class="eyebrow">Programa de indicação</div><h1>Indique e ganhe créditos</h1><div v-if="!affiliates" class="spa-empty spa-card"><h2>Convide seus amigos</h2><p>Entre na conta para criar e acompanhar seu link de indicação.</p><a class="spa-primary" href="/login">Entrar</a></div><template v-else><div class="spa-card spa-referral"><span class="spa-muted">Seu link pessoal</span><div><code>{{ affiliates.stats.referral_link }}</code><button class="spa-secondary" @click="copy(affiliates.stats.referral_link)">Copiar</button></div></div><div class="spa-grid spa-grid--four"><div class="spa-card spa-metric"><span>Indicações</span><strong>{{ affiliates.stats.total_referrals }}</strong></div><div class="spa-card spa-metric"><span>Volume gerado</span><strong>{{ credits(affiliates.stats.total_volume) }}</strong></div><div class="spa-card spa-metric"><span>Créditos pendentes</span><strong>{{ credits(affiliates.stats.unclaimed_commissions) }}</strong><button class="spa-primary" @click="claim('/spa/api/affiliates/claim')">Resgatar</button></div></div></template></section></template>
      <template v-else><section class="spa-section spa-info"><div class="eyebrow">Promex</div><h1>{{ currentInfo[0] }}</h1><p class="spa-muted">{{ currentInfo[1] }}</p><div class="spa-grid"><article v-for="block in currentInfo.slice(2)" :key="block[0]" class="spa-card"><h2>{{ block[0] }}</h2><p class="spa-muted">{{ block[1] }}</p></article></div><div class="spa-actions"><a v-if="!state.user" class="spa-primary" href="/register">Criar conta</a><button class="spa-secondary" @click="go('/app')">Voltar ao início</button></div></section></template>
    </main><nav class="spa-mobile-nav" aria-label="Navegação mobile"><a v-for="[to, icon, label] in mobileNav" :key="to" :href="to" :class="{active: path === to}" @click.prevent="go(to)"><Icon :name="icon" :size="18"/><span>{{ label }}</span></a></nav><div v-if="launching" class="spa-launch" role="status" aria-live="assertive"><div><span>Preparando experiência</span><strong>{{ launching.title }}</strong><i></i></div></div>
  </div>
</template>
